package com.lmspilot.operations.domain; import jakarta.persistence.*; import java.time.Instant; import java.util.UUID; @Entity @Table(name="operation_jobs") public class OperationJobEntity{@Id private UUID id=UUID.randomUUID();@Enumerated(EnumType.STRING)@Column(nullable=false,length=30)private OperationType type=OperationType.BACKUP;@Enumerated(EnumType.STRING)@Column(nullable=false,length=30)private OperationStatus status=OperationStatus.REQUESTED;@Column(nullable=false)private UUID requestedBy;@Column(nullable=false)private Instant requestedAt=Instant.now();private Instant startedAt;private Instant finishedAt;@Column(columnDefinition="text")private String parametersJson="{}";@Column(columnDefinition="text")private String resultJson;@Column(columnDefinition="text")private String errorMessage;@Column(length=160)private String claimedBy;@Column(length=120)private String claimToken;private Instant heartbeatAt;private Instant leaseUntil;@Column(nullable=false)private int attemptCount;public OperationJobEntity(){}public OperationJobEntity(OperationType t,UUID u,String p){type=t;requestedBy=u;parametersJson=p;}public UUID getId(){return id;}public OperationType getType(){return type;}public OperationStatus getStatus(){return status;}public void setStatus(OperationStatus v){status=v;}public UUID getRequestedBy(){return requestedBy;}public Instant getRequestedAt(){return requestedAt;}public Instant getStartedAt(){return startedAt;}public void setStartedAt(Instant v){startedAt=v;}public Instant getFinishedAt(){return finishedAt;}public void setFinishedAt(Instant v){finishedAt=v;}public String getParametersJson(){return parametersJson;}public String getResultJson(){return resultJson;}public void setResultJson(String v){resultJson=v;}public String getErrorMessage(){return errorMessage;}public void setErrorMessage(String v){errorMessage=v;}public String getClaimedBy(){return claimedBy;}public void setClaimedBy(String v){claimedBy=v;}public String getClaimToken(){return claimToken;}public void setClaimToken(String v){claimToken=v;}public Instant getHeartbeatAt(){return heartbeatAt;}public void setHeartbeatAt(Instant v){heartbeatAt=v;}public Instant getLeaseUntil(){return leaseUntil;}public void setLeaseUntil(Instant v){leaseUntil=v;}public int getAttemptCount(){return attemptCount;}public void setAttemptCount(int v){attemptCount=v;}}
